package com.bookstore.entity;
import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.*;
@Entity @Table(name="orders") public class Order { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private User user; private LocalDateTime createdAt=LocalDateTime.now(); @Enumerated(EnumType.STRING) private OrderStatus status=OrderStatus.PLACED; private double total; private String paymentMethod="DEMO"; private String shippingAddress;
 public Order(){} public Order(User u,double t,String a,String p){user=u;total=t;shippingAddress=a;paymentMethod=p;} public Long getId(){return id;} public User getUser(){return user;} public LocalDateTime getCreatedAt(){return createdAt;} public OrderStatus getStatus(){return status;} public void setStatus(OrderStatus s){status=s;} public double getTotal(){return total;} public String getPaymentMethod(){return paymentMethod;} public String getShippingAddress(){return shippingAddress;}}
